fn process_r1_cost_probe_instruction(program_id:&Pubkey,accounts:&[AccountInfo],data:&[u8])->ProgramResult{
    #[cfg(feature="pool-adapter")]
    {
        // Reject before inspecting or borrowing any account. Lifecycle loaders
        // are not part of the release instruction surface.
        if !pool_route::admitted(data) {
            return Err(ProgramError::InvalidInstructionData);
        }
        return r1_pool_adapter::process(program_id,accounts,data);
    }

    #[cfg(not(feature="pool-adapter"))]
    {
    if accounts.len()!=3||!matches!(data,[1,0..=22]|[2]) {return Err(ProgramError::InvalidInstructionData);}
    for (i,a) in accounts.iter().enumerate(){if a.owner!=program_id||a.executable||a.is_writable!=(i==2){return Err(ProgramError::InvalidAccountData);}}
    let proof=accounts[0].try_borrow_data()?;let public=accounts[1].try_borrow_data()?;let mut checkpoint=accounts[2].try_borrow_mut_data()?;
    msg!("UNPROVED R1 COST PROBE");msg!("r1:begin");sol_log_compute_units();
    if data[0]==1 {
        if checkpoint.iter().any(|&b|b!=0){return Err(ProgramError::AccountAlreadyInitialized);}
        let bytes=first(&public,&proof,data[1]as usize)?;
        if checkpoint.len()!=bytes.len(){return Err(ProgramError::InvalidAccountData);}
        checkpoint.copy_from_slice(&bytes);
    } else {
        verifier::tx2(&public,&proof,&checkpoint,SolanaDigest,observer()).map_err(error)?;
        checkpoint[10]=2;let end=checkpoint.len()-32;let sum=hashv(&[b"UNPROVED:R1:checkpoint",&checkpoint[..end]]).to_bytes();checkpoint[end..].copy_from_slice(&sum);
    }
    msg!("r1:account-write");sol_log_compute_units();
    #[cfg(target_os="solana")]
    unsafe {
        let cursor=*(solana_program::entrypoint::HEAP_START_ADDRESS as *const usize);
        msg!("r1:heap-high-water");solana_program::log::sol_log_64((solana_program::entrypoint::HEAP_START_ADDRESS as usize+256*1024-cursor+core::mem::size_of::<usize>())as u64,0,0,0,0);
    }
    Ok(())
    }
}

fn admitted(data: &[u8]) -> bool {
    data == [3, 10] || data == [3, 11] || data.starts_with(b"ASQ8")
}

fn readonly_buffer_meta_ok(
    is_signer: bool,
    is_writable: bool,
    executable: bool,
) -> ProgramResult {
    if is_signer || is_writable || executable {
        return Err(ProgramError::InvalidAccountData);
    }
    Ok(())
}

fn require_verifier_checkpoint(
    account: &AccountInfo<'_>,
    program_id: &Pubkey,
    writable: bool,
) -> ProgramResult {
    if account.owner != program_id || account.is_signer || account.executable
        || account.is_writable != writable
        || account.try_data_len()? != verifier::checkpoint_size(Variant::S2)
    {
        return Err(ProgramError::InvalidAccountData);
    }
    Ok(())
}

fn lifecycle_init(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    instruction_data: &[u8],
) -> ProgramResult {
    if instruction_data.len() != 2 || instruction_data[0] != 4 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let kind = LifecycleKind::from_byte(instruction_data[1])?;
    let (target, authority) = lifecycle_accounts(program_id, accounts)?;
    let body_len = kind.body_len()?;
    if u32::try_from(body_len).is_err() {
        return Err(ProgramError::InvalidInstructionData);
    }
    let mut target_data = target.try_borrow_mut_data()?;
    if target_data.len() != ASPU_HEADER + body_len || target_data.iter().any(|byte| *byte != 0) {
        return Err(ProgramError::AccountAlreadyInitialized);
    }
    target_data[..4].copy_from_slice(&kind.magic());
    target_data[4..8].copy_from_slice(&(body_len as u32).to_le_bytes());
    target_data[ASPU_AUTHORITY.clone()].copy_from_slice(authority.key.as_ref());
    Ok(())
}

fn lifecycle_write(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    instruction_data: &[u8],
) -> ProgramResult {
    if instruction_data.len() <= 5 || instruction_data[0] != 5 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let (target, authority) = lifecycle_accounts(program_id, accounts)?;
    let offset = u32::from_le_bytes(
        instruction_data[1..5]
            .try_into()
            .map_err(|_| ProgramError::InvalidInstructionData)?,
    ) as usize;
    let payload = &instruction_data[5..];
    let kind = {
        let target_data = target.try_borrow_data()?;
        validate_lifecycle_header(&target_data, authority.key, false)?
    };
    let end = offset
        .checked_add(payload.len())
        .ok_or(ProgramError::InvalidInstructionData)?;
    if end > kind.writable_prefix_len()? || end > kind.body_len()? {
        return Err(ProgramError::InvalidInstructionData);
    }
    let mut target_data = target.try_borrow_mut_data()?;
    let start = ASPU_HEADER
        .checked_add(offset)
        .ok_or(ProgramError::InvalidInstructionData)?;
    let write_end = start
        .checked_add(payload.len())
        .ok_or(ProgramError::InvalidInstructionData)?;
    target_data[start..write_end].copy_from_slice(payload);
    Ok(())
}

fn lifecycle_finalize(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    instruction_data: &[u8],
) -> ProgramResult {
    if instruction_data != &[6] {
        return Err(ProgramError::InvalidInstructionData);
    }
    let (target, authority) = lifecycle_accounts(program_id, accounts)?;
    let kind = {
        let target_data = target.try_borrow_data()?;
        let kind = validate_lifecycle_header(&target_data, authority.key, false)?;
        validate_lifecycle_final_body(&target_data, kind)?;
        kind
    };
    let mut target_data = target.try_borrow_mut_data()?;
    if target_data[..4] != kind.magic() {
        return Err(ProgramError::InvalidAccountData);
    }
    target_data[ASPU_AUTHORITY.clone()].fill(0);
    Ok(())
}

fn scan_proof_buffer(bytes: &[u8]) -> Result<ScannedAsqaProof, ProgramError> {
    let proof_length = verifier::PROOF_BYTES;
    let expected_body = POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES
        .checked_add(proof_length)
        .ok_or(ProgramError::InvalidAccountData)?;
    if bytes.len() != expected_body {
        return Err(ProgramError::InvalidAccountData);
    }
    let candidate_start = 0;
    let proof_start = candidate_start + POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES;
    let candidate_bytes = &bytes[candidate_start..proof_start];
    let candidate = Box::new(
        decode_pool_v1_pair_verified_afterstate_v1(candidate_bytes)
            .map_err(|_| ProgramError::InvalidAccountData)?,
    );
    if encode_pool_v1_pair_verified_afterstate_v1(&candidate)
        .map_err(|_| ProgramError::InvalidAccountData)?
        .as_ref()
        != candidate_bytes
        || bytes[proof_start + 8] != Variant::S2.tag()
    {
        return Err(ProgramError::InvalidAccountData);
    }
    Ok(ScannedAsqaProof {
        candidate_afterstate: candidate,
        proof_length,
    })
}

fn validate_asq8(
    verifier_program: &Pubkey,
    accounts: &[AccountInfo<'_>],
    instruction_data: &[u8],
) -> Result<ValidatedAsqa, ProgramError> {
    if instruction_data.len() != POOL_V1_PAIR_FOREST_TERMINAL_REQUEST_BYTES {
        return Err(ProgramError::InvalidInstructionData);
    }
    let request = decode_pool_v1_pair_forest_terminal_request_v1(instruction_data)
        .map_err(|_| ProgramError::InvalidInstructionData)?;
    if request.verifier_profile != PROFILE_BINDING
        || request.verifier_release != RELEASE_BINDING
        || request.pool_program != pool_program_id()
    {
        return Err(ProgramError::InvalidInstructionData);
    }
    let pool_program = Pubkey::new_from_array(request.pool_program);
    let output_lane = pool_v1_pair_forest_output_lane_v1(request.public.nullifier())
        .map_err(|_| ProgramError::InvalidInstructionData)?;
    let authenticated = authenticate_asq8_accounts(
        verifier_program,
        accounts,
        &pool_program,
        output_lane,
        Clock::get()?.slot,
    )?;
    let proof_account = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let scanned = scan_proof_buffer(&proof_account.try_borrow_data()?)?;
    let statement =
        reconstruct_asq8_statement(&request, &authenticated, &scanned.candidate_afterstate)?;
    Ok(ValidatedAsqa {
        statement,
        proof_length: scanned.proof_length,
    })
}

fn stage1(program_id: &Pubkey, accounts: &[AccountInfo<'_>], data: &[u8]) -> ProgramResult {
    if !(data == &[3, 10] || data == &[3, 11]) || accounts.len() != 3 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let proof_account = &accounts[0];
    let public_account = &accounts[1];
    let checkpoint_account = &accounts[2];
    require_distinct_accounts(&[proof_account, public_account, checkpoint_account])?;
    require_readonly_buffer(proof_account)?;
    require_readonly_buffer(public_account)?;
    require_verifier_checkpoint(checkpoint_account, program_id, true)?;
    let mut checkpoint_data = checkpoint_account.try_borrow_mut_data()?;
    if checkpoint_data.iter().any(|byte| *byte != 0) {
        return Err(ProgramError::AccountAlreadyInitialized);
    }
    let public_data = public_account.try_borrow_data()?;
    let statement = decode_public_statement_box(&public_data)?;
    validate_pool_v1_pair_forest_terminal_statement_v1(&statement)
        .map_err(|_| ProgramError::InvalidAccountData)?;
    let candidate = encode_pool_v1_pair_verified_afterstate_v1(
        &statement.common().lane_transition.candidate_afterstate,
    )
    .map_err(|_| ProgramError::InvalidAccountData)?;

    let proof_data = proof_account.try_borrow_data()?;
    let proof_length = verifier::PROOF_BYTES;
    let proof_start = POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES;
    let proof_end = proof_start.checked_add(proof_length)
        .ok_or(ProgramError::InvalidAccountData)?;
    if proof_data.len() != proof_end
        || proof_data[..proof_start] != candidate
        || proof_data[proof_start + 8] != Variant::S2.tag()
    {
        return Err(ProgramError::InvalidAccountData);
    }
    let checkpoint = super::first_decoded(statement.semantic_public(), &public_data, &proof_data[proof_start..proof_end], data[1] as usize)?;
    if checkpoint.len() != checkpoint_data.len() {
        return Err(ProgramError::InvalidAccountData);
    }
    checkpoint_data.copy_from_slice(&checkpoint);
    #[cfg(feature="cu-profiling")]
    {
    msg!("r1:pool-adapter-stage1-checkpoint-written");
    solana_program::log::sol_log_compute_units();
    }
    Ok(())
}

fn stage2(program_id: &Pubkey, accounts: &[AccountInfo<'_>], data: &[u8]) -> ProgramResult {
    if accounts.len() != 7 || data.get(..4) != Some(&POOL_V1_PAIR_FOREST_TERMINAL_REQUEST_MAGIC[..])
    {
        return Err(ProgramError::InvalidInstructionData);
    }
    program::set_return_data(&[]);
    #[cfg(feature="cu-profiling")]
    {
    msg!("r1:pool-adapter-stage2-begin");
    solana_program::log::sol_log_compute_units();
    }
    let validated = validate_asq8(program_id, accounts, data)?;
    let proof_data = accounts[0].try_borrow_data()?;
    let checkpoint_data = accounts[6].try_borrow_data()?;
    let proof_start = POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES;
    let proof_end = proof_start.checked_add(validated.proof_length)
        .ok_or(ProgramError::InvalidAccountData)?;
    if proof_data.len() != proof_end {
        return Err(ProgramError::InvalidAccountData);
    }
    let public_bytes = encode_pool_v1_pair_forest_terminal_statement_v1(&validated.statement)
        .map_err(|_| ProgramError::InvalidInstructionData)?;
    if public_bytes.len() != POOL_V1_PAIR_FOREST_TERMINAL_STATEMENT_BYTES {
        return Err(ProgramError::InvalidInstructionData);
    }
    verifier::tx2_authenticated(
        &public_bytes,
        &proof_data[proof_start..proof_end],
        &checkpoint_data,
        super::SolanaDigest,
        super::observer(),
    )
    .map_err(super::error)?;
    emit_result(&validated.statement)
}

fn proof_transport_verifier(
    verifier_program: &AccountInfo<'_>,
    proof: &AccountInfo<'_>,
    verifier_checkpoint: Option<&AccountInfo<'_>>,
) -> Result<Pubkey, ProgramError> {
    #[cfg(feature = "r1-split-checkpoint")]
    {
        let checkpoint = verifier_checkpoint.ok_or(ProgramError::NotEnoughAccountKeys)?;
        if proof.key == verifier_program.key
            || proof.executable
            || proof.is_signer
            || proof.is_writable
            || checkpoint.owner != verifier_program.key
            || checkpoint.executable
            || checkpoint.is_signer
            || checkpoint.is_writable
            || checkpoint.key == proof.key
            || checkpoint.key == verifier_program.key
        {
            return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
        }
        // The verifier checks the exact checkpoint size and authenticated bytes.
        Ok(*verifier_program.key)
    }
    #[cfg(not(feature = "r1-split-checkpoint"))]
    {
        if verifier_checkpoint.is_some() {
            return Err(ProgramError::InvalidArgument);
        }
        let claim = derive_pair_verifier_account_claim_v1(verifier_program, proof)?;
        Ok(Pubkey::new_from_array(claim.verifier_program))
    }
}

fn resume<H:Digest32>(bytes:&[u8],proof:&[u8],public:&[u8],v:Variant,hash:H)->Result<(Box<Prepared>,Accumulator),Error> {
    if bytes.len()!=checkpoint_size(v)||&bytes[..8]!=b"R1P2CKP2"||bytes[8]!=v.tag()||bytes[9]>22||bytes[10]!=1||bytes[11..16].iter().any(|&b|b!=0) {return Err(Error::Checkpoint);}
    let end=bytes.len()-32;
    if bytes[16..48]!=hash.digest(&[proof])||bytes[48..80]!=hash.digest(&[public])||bytes[end..]!=hash.digest(&[b"UNPROVED:R1:checkpoint",&bytes[..end]]) {return Err(Error::Checkpoint);}
    let mut r=Reader{bytes,at:80};let state=r.raw();let roots=[r.raw(),r.raw()];
    let gamma=r.e()?;let kappa=r.e()?;let alpha=[r.e()?,r.e()?];let rho=r.k()?;
    let queries=[
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
        u32::from_le_bytes(r.raw()),
    ];
    validate_checkpoint_queries(&queries)?;
    let (semantic_alpha,at)=read_checkpoint_semantic_alpha(bytes,r.at)?;
    r.at=at;
    let z=[SecureCirclePoint{x:r.k()?,y:r.k()?},SecureCirclePoint{x:r.k()?,y:r.k()?}];
    let claim=r.e()?;let rhs=r.e()?;let power=r.k()?;
    let weights=aspis_core::r0::heap::filled(v.final_len(),K::ZERO).map_err(|_|Error::Allocation)?;
    let (weights,at)=read_checkpoint_weights(bytes,r.at,weights)?;
    if at!=end {return Err(Error::Checkpoint);}
    Ok((Box::new(Prepared{variant:v,roots,gamma,kappa,alpha,rho,queries,semantic_alpha,z,claim,state}),Accumulator{weights,rhs,power,next:bytes[9] as usize}))
}
